  "inlineSchema": "// Restaurant Loyalty PWA — data model\n//\n// The rule that shapes everything here: a customer belongs to the company, not\n// to a branch. Only a Transaction carries a branchId. That is what lets points\n// earned in one branch be spent in another while branch reporting still works.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"./client\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------------------------------------------------------------- branches\n\nmodel Branch {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  name      String\n  nameAr    String? // Arabic name\n  address   String?\n  addressAr String?\n  phone     String?\n  hours     String?\n  city      String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  homeCustomers Customer[]    @relation(\"HomeBranch\")\n  staff         Staff[]\n  transactions  Transaction[]\n  offers        OfferBranch[]\n\n  @@index([isActive])\n}\n\n// ---------------------------------------------------------------- customers\n\nmodel Customer {\n  id        String    @id @default(cuid())\n  mobile    String    @unique // E.164, the login identity\n  name      String\n  email     String?\n  birthday  DateTime? @db.Date\n  language  String    @default(\"en\") // \"en\" | \"ar\"\n  isBlocked Boolean   @default(false)\n\n  homeBranchId String?\n  homeBranch   Branch? @relation(\"HomeBranch\", fields: [homeBranchId], references: [id])\n\n  pointsBalance Int       @default(0)\n  visitCount    Int       @default(0)\n  totalSpend    Decimal   @default(0) @db.Decimal(12, 2)\n  lastVisitAt   DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  qrTokens        QrToken[]\n  transactions    Transaction[]\n  pointsLedger    PointsLedger[]\n  customerRewards CustomerReward[]\n\n  @@index([homeBranchId])\n  @@index([createdAt])\n  @@index([lastVisitAt])\n}\n\n// One-time codes for sign-up and sign-in.\nmodel OtpCode {\n  id         String    @id @default(cuid())\n  mobile     String\n  codeHash   String // hashed, never stored in the clear\n  purpose    String    @default(\"register\") // \"register\" | \"login\"\n  attempts   Int       @default(0)\n  expiresAt  DateTime\n  consumedAt DateTime?\n  createdAt  DateTime  @default(now())\n\n  pendingName     String?\n  pendingEmail    String?\n  pendingBirthday DateTime? @db.Date\n  pendingBranchId String?\n\n  @@index([mobile, purpose])\n  @@index([expiresAt])\n}\n\n// The QR shown on the loyalty card. Short-lived by design.\nmodel QrToken {\n  id         String    @id @default(cuid())\n  token      String    @unique\n  customerId String\n  customer   Customer  @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  expiresAt  DateTime\n  usedAt     DateTime?\n  createdAt  DateTime  @default(now())\n\n  @@index([customerId])\n  @@index([expiresAt])\n}\n\n// ---------------------------------------------------------------- staff\n\nmodel Staff {\n  id       String  @id @default(cuid())\n  username String  @unique\n  name     String\n  pinHash  String // scrypt hash of the till PIN\n  role     Role    @default(CASHIER)\n  isActive Boolean @default(true)\n\n  branchId String?\n  branch   Branch? @relation(fields: [branchId], references: [id])\n\n  createdAt DateTime  @default(now())\n  lastLogin DateTime?\n\n  transactions Transaction[]\n  auditLogs    AuditLog[]\n\n  @@index([branchId])\n}\n\nenum Role {\n  SUPER_ADMIN\n  COMPANY_ADMIN\n  BRANCH_MANAGER\n  CASHIER\n}\n\n// ---------------------------------------------------------------- transactions\n\nmodel Transaction {\n  id         String   @id @default(cuid())\n  customerId String\n  customer   Customer @relation(fields: [customerId], references: [id])\n  branchId   String\n  branch     Branch   @relation(fields: [branchId], references: [id])\n  staffId    String?\n  staff      Staff?   @relation(fields: [staffId], references: [id])\n\n  invoiceNumber String\n  amount        Decimal @db.Decimal(12, 2)\n  pointsEarned  Int     @default(0)\n  discountGiven Decimal @default(0) @db.Decimal(12, 2)\n\n  isReversed    Boolean   @default(false)\n  reversedAt    DateTime?\n  reverseReason String?\n\n  createdAt DateTime @default(now())\n\n  pointsLedger    PointsLedger[]\n  customerRewards CustomerReward[]\n\n  @@unique([branchId, invoiceNumber])\n  @@index([customerId])\n  @@index([branchId, createdAt])\n  @@index([createdAt])\n}\n\n// Points ledger audit trail\nmodel PointsLedger {\n  id            String       @id @default(cuid())\n  customerId    String\n  customer      Customer     @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  transactionId String?\n  transaction   Transaction? @relation(fields: [transactionId], references: [id])\n\n  delta  Int // positive to earn, negative to redeem\n  reason String // \"purchase\" | \"reward_redemption\" | \"welcome\" | \"referral\" | \"birthday\" | \"correction\" | \"expiry\"\n  note   String?\n\n  createdAt DateTime  @default(now())\n  expiresAt DateTime?\n\n  @@index([customerId, createdAt])\n  @@index([expiresAt])\n}\n\n// ---------------------------------------------------------------- rewards\n\nmodel Reward {\n  id            String  @id @default(cuid())\n  name          String\n  nameAr        String?\n  description   String?\n  descriptionAr String?\n\n  type      RewardType\n  threshold Int // points needed, or visit number\n  value     Decimal    @default(0) @db.Decimal(12, 2)\n  isPercent Boolean    @default(false)\n\n  validDays Int?     @default(30)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  customerRewards CustomerReward[]\n\n  @@index([isActive])\n}\n\nenum RewardType {\n  WELCOME\n  POINTS\n  VISITS\n  BIRTHDAY\n  REFERRAL\n  MANUAL\n}\n\n// A reward that has been issued to a customer\nmodel CustomerReward {\n  id         String   @id @default(cuid())\n  customerId String\n  customer   Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  rewardId   String\n  reward     Reward   @relation(fields: [rewardId], references: [id])\n\n  status     RewardStatus @default(AVAILABLE)\n  issuedAt   DateTime     @default(now())\n  expiresAt  DateTime?\n  redeemedAt DateTime?\n\n  redeemedTxId String?\n  redeemedTx   Transaction? @relation(fields: [redeemedTxId], references: [id])\n\n  @@index([customerId, status])\n  @@index([expiresAt])\n}\n\nenum RewardStatus {\n  AVAILABLE\n  REDEEMED\n  EXPIRED\n}\n\n// ---------------------------------------------------------------- offers\n\nmodel Offer {\n  id            String  @id @default(cuid())\n  name          String\n  nameAr        String?\n  description   String?\n  descriptionAr String?\n\n  discountValue Decimal @default(0) @db.Decimal(12, 2)\n  isPercent     Boolean @default(true)\n\n  segment   String?\n  startsAt  DateTime?\n  endsAt    DateTime?\n  isActive  Boolean   @default(true)\n  createdAt DateTime  @default(now())\n\n  branches OfferBranch[]\n\n  @@index([isActive])\n}\n\nmodel OfferBranch {\n  offerId  String\n  offer    Offer  @relation(fields: [offerId], references: [id], onDelete: Cascade)\n  branchId String\n  branch   Branch @relation(fields: [branchId], references: [id], onDelete: Cascade)\n\n  @@id([offerId, branchId])\n}\n\n// ---------------------------------------------------------------- audit\n\nmodel AuditLog {\n  id      String  @id @default(cuid())\n  staffId String?\n  staff   Staff?  @relation(fields: [staffId], references: [id])\n\n  action     String\n  entityType String?\n  entityId   String?\n  reason     String?\n  metadata   Json?\n\n  createdAt DateTime @default(now())\n\n  @@index([createdAt])\n  @@index([staffId])\n  @@index([action])\n}\n\n// ---------------------------------------------------------------- settings\n\nmodel Setting {\n  key       String   @id\n  value     String\n  updatedAt DateTime @updatedAt\n}\n",
